from E31_target import fibonacci, is_palindrome


# ========== fibonacci tests ==========

# --- Normal cases ---

class TestFibonacciNormal:
    def test_fib_zero(self):
        assert fibonacci(0) == 0

    def test_fib_one(self):
        assert fibonacci(1) == 1

    def test_fib_two(self):
        assert fibonacci(2) == 1

    def test_fib_three(self):
        assert fibonacci(3) == 2

    def test_fib_ten(self):
        assert fibonacci(10) == 55

    def test_fib_twenty(self):
        assert fibonacci(20) == 6765


# --- Edge cases ---

class TestFibonacciEdge:
    def test_fib_large_number(self):
        # fibonacci(100) = 354224848179261915075
        assert fibonacci(100) == 354224848179261915075

    def test_fib_consecutive_values(self):
        prev = fibonacci(5)
        curr = fibonacci(6)
        nxt = fibonacci(7)
        assert prev + curr == nxt


# --- Error cases ---

class TestFibonacciError:
    def test_fib_negative(self):
        with pytest.raises(ValueError, match='n must be non-negative'):
            fibonacci(-1)

    def test_fib_negative_large(self):
        with pytest.raises(ValueError, match='n must be non-negative'):
            fibonacci(-100)

    def test_fib_float(self):
        with pytest.raises(TypeError):
            fibonacci(5.5)

    def test_fib_string(self):
        with pytest.raises(TypeError):
            fibonacci("10")

    def test_fib_none(self):
        with pytest.raises(TypeError):
            fibonacci(None)


# ========== is_palindrome tests ==========

# --- Normal cases ---

class TestIsPalindromeNormal:
    def test_palindrome_simple(self):
        assert is_palindrome("racecar") is True

    def test_palindrome_even_length(self):
        assert is_palindrome("abba") is True

    def test_not_palindrome(self):
        assert is_palindrome("hello") is False

    def test_single_char(self):
        assert is_palindrome("a") is True

    def test_empty_string(self):
        assert is_palindrome("") is True


# --- Edge cases ---

class TestIsPalindromeEdge:
    def test_palindrome_with_spaces(self):
        assert is_palindrome("  racecar  ") is True

    def test_palindrome_mixed_case(self):
        assert is_palindrome("RaceCar") is True

    def test_palindrome_with_spaces_and_case(self):
        assert is_palindrome("  A  ") is True

    def test_palindrome_numbers(self):
        assert is_palindrome("12321") is True

    def test_not_palindrome_numbers(self):
        assert is_palindrome("12345") is False

    def test_palindrome_special_chars(self):
        assert is_palindrome("!@# @!") is True  # after strip+lower: "!@# @!" -> "!@# @!" which reversed is "!@ #@!" ... let me use a clear one
        assert is_palindrome("!!!") is True

    def test_palindrome_unicode(self):
        # "amanaplanacanalpanama" is a palindrome
        assert is_palindrome("AmanaplanacanalPanama") is True


# --- Error cases ---

class TestIsPalindromeError:
    def test_palindrome_none(self):
        with pytest.raises(AttributeError):
            is_palindrome(None)

    def test_palindrome_int(self):
        with pytest.raises(AttributeError):
            is_palindrome(12321)

    def test_palindrome_list(self):
        with pytest.raises(AttributeError):
            is_palindrome(["r", "a", "c", "e", "c", "a", "r"])
"}

